                <form class="cc-list-tools" @submit.prevent="fetchCalls(1)"><div class="cc-search-row"><input type="search" v-model.trim="filters.search" aria-label="Search call log" placeholder="Call reference, caller, or phone" maxlength="100"><button class="cc-button secondary small" :disabled="loading">Find</button></div><details><summary>More filters</summary><div class="cc-grid"><div v-if="queue === 'today' || queue === 'all'" class="cc-field"><label for="filter-date">Date</label><input id="filter-date" type="date" v-model="filters.date"></div><div class="cc-field"><label for="filter-shift">Shift</label><select id="filter-shift" v-model="filters.shift"><option value="">All shifts</option><option v-for="shift in options.shifts" :key="shift" :value="shift">Shift {{ shift }}</option></select></div><div v-if="queue !== 'open_complaints'" class="cc-field"><label for="filter-category">Category</label><select id="filter-category" v-model="filters.category"><option value="">All categories</option><option v-for="item in options.categories" :key="item.value" :value="item.value">{{ item.label }}</option></select></div><div v-if="queue === 'today' || queue === 'all'" class="cc-field"><label for="filter-status">Status</label><select id="filter-status" v-model="filters.status"><option value="">All statuses</option><option v-for="item in options.statuses" :key="item.value" :value="item.value">{{ item.label }}</option></select></div><div v-if="options.permissions.all_terminals" class="cc-field"><label for="filter-terminal">Terminal</label><select id="filter-terminal" v-model="filters.terminal_id"><option value="">All permitted terminals</option><option v-for="terminal in options.terminals" :key="terminal.id" :value="terminal.id">{{ terminal.name }}</option></select></div></div><button class="cc-button secondary small" :disabled="loading">Apply filters</button></details></form>
                <div v-if="listError" class="cc-alert" role="alert">{{ listError }} <button class="cc-link" @click="fetchCalls(1)">Try again</button></div><div v-else-if="loading" class="cc-empty" role="status">Loading calls…</div><div v-else-if="!calls.length" class="cc-empty"><h3>{{ queue === 'callbacks_due' ? 'No callbacks due' : queue === 'open_complaints' ? 'No open complaints' : 'No calls found' }}</h3><p>{{ queue === 'callbacks_due' ? 'Future callbacks will appear here when due.' : 'Try another queue or record a new call.' }}</p></div>
                <article v-for="call in loading ? [] : calls" :key="call.id" class="cc-work-item"><div class="cc-card-header compact"><strong>{{ call.reference }} · {{ call.caller_name || call.caller_phone || 'Caller not recorded' }}</strong><span class="cc-status" :class="call.status">{{ statusLabel(call.status) }}</span></div><p>{{ categoryLabel(call.category) }}<span v-if="call.inquiry_topic"> · {{ topicLabel(call.inquiry_topic) }}</span></p><p class="cc-muted">{{ call.caller_phone || 'No phone recorded' }} · {{ time(call.called_at) }}</p><p v-if="journeySummary(call)" class="cc-muted">{{ journeySummary(call) }}</p><p v-if="call.remarks" class="cc-work-note">{{ call.remarks }}</p><p v-if="call.callback_at && call.status !== 'closed'" :class="{ 'cc-overdue': isDue(call.callback_at) }">{{ isDue(call.callback_at) ? 'Callback due' : 'Callback' }} · {{ time(call.callback_at) }}</p><p v-if="call.assignee" class="cc-muted">Responsible: {{ call.assignee.name }}</p><div class="cc-actions"><button class="cc-button secondary small" @click="openCall(call.id)" :disabled="opening || saving">Open</button><button class="cc-link" v-if="canFollowup" @click="startFollowup(call)" :disabled="saving || opening">Follow up</button></div></article>
                <div class="cc-pagination"><span>Page {{ pagination.current_page }} of {{ pagination.last_page || 1 }}</span><div class="cc-actions"><button class="cc-button secondary small" :disabled="loading || pagination.current_page <= 1" @click="fetchCalls(pagination.current_page - 1)">Previous</button><button class="cc-button secondary small" :disabled="loading || pagination.current_page >= pagination.last_page" @click="fetchCalls(pagination.current_page + 1)">Next</button></div></div>
            </section>
