        </div>
    </div>
</template>

<script>
import PassengerLookup from './PassengerLookup.vue';
import QuickAnswers from './QuickAnswers.vue';
import { request, pakistanDate, callbackValue, inputDateTime, displayTime, callQueueParams, savedShift, rememberShift, bookingTime } from './callCenter';
function blankCall(shift = '') { return { call_date: pakistanDate(), shift, category: 'GI', inquiry_topic: '', status: 'new', caller_name: '', caller_phone: '', customer_id: null, ticket_id: null, seat_count: 0, remarks: '', assigned_to: '', callback_at: '', parent_call_id: '', external_reference: '', complaint_from_city: '', complaint_to_city: '', complaint_bus_time: '', complaint_seat_number: '' }; }
export default {
    components: { PassengerLookup, QuickAnswers }, props: { options: { type: Object, required: true } },
    data() {
        const form = blankCall(savedShift(this.options.current_user.id));
        return { journeyCities: [], citiesLoaded: false, citiesLoading: false, callerDetailsOpen: false, discardVisible: false, discardResolve: null, returnFocus: null, form, baseline: JSON.stringify(form), editing: null, calls: [], queue: 'today', filters: { date: pakistanDate(), shift: '', category: '', status: '', search: '', terminal_id: '' }, pagination: { total: 0, current_page: 1, last_page: 1 }, loading: false, listError: '', requestNumber: 0, saving: false, savingOutcome: '', opening: false, openNumber: 0, formError: '', fieldErrors: {}, notice: '', lastSavedComplaint: false, selectedPassenger: null, selectedTicket: null, lookupKey: 0, needsFollowup: false, resolveParent: false, parentCall: null, showParentSearch: false, earlierSearch: '', earlierCalls: [], parentError: '', parentLoading: false, parentSearched: false, parentNumber: 0, history: null, historyError: '', historyLoading: false, historyNumber: 0,
            topics: [{ value: 'fare', label: 'Fare' }, { value: 'timings', label: 'Timings' }, { value: 'terminal', label: 'Terminal location' }], queues: [{ value: 'today', label: 'Today’s calls' }, { value: 'callbacks_due', label: 'Callbacks due' }, { value: 'open_complaints', label: 'Open complaints' }, { value: 'all', label: 'All calls' }] };
    },
    computed: {
        hasJourneyDetails() { return ['C', 'BK'].includes(this.form.category); },
        editable() { return this.editing ? this.options.permissions.update && (this.form.category !== 'FU' || this.options.permissions.follow_up) : this.options.permissions.create; },
        canFollowup() { return this.options.permissions.create && this.options.permissions.follow_up && this.options.permissions.view_calls; },
        availableCategories() { return this.options.categories.filter(item => (item.value !== 'FU' || this.canFollowup || this.editing?.category === 'FU') && (!this.editing || this.editing.category !== 'C' || item.value === 'C' || (this.options.permissions.view_complaints && this.options.permissions.close_complaints && (this.editing.status !== 'closed' || this.options.permissions.reopen_complaints)))); },
        canResolveParent() { if (!this.parentCall) return false; return this.parentCall.category === 'C' ? this.options.permissions.view_complaints && this.options.permissions.close_complaints : this.options.permissions.update; },
        dirty() { return JSON.stringify(this.form) !== this.baseline || this.resolveParent; },
        historyCalls() { const rows = [...(this.history?.open_complaints || []), ...(this.history?.recent_calls || [])]; return rows.filter((call, i) => rows.findIndex(other => other.id === call.id) === i); },
    },
    mounted() { this.fetchCalls(1); window.addEventListener('beforeunload', this.beforeUnload); },
    beforeUnmount() { this.requestNumber++; this.openNumber++; this.historyNumber++; this.parentNumber++; window.removeEventListener('beforeunload', this.beforeUnload); },
    methods: {
        time: displayTime, today: pakistanDate,
        yesterday() { return pakistanDate(new Date(Date.now() - 86400000)); },
        categoryLabel(value) { return this.options.categories.find(item => item.value === value)?.label || value; },
        statusLabel(value) { return value === 'closed' ? 'Finished' : value === 'waiting' ? 'Follow-up needed' : this.options.statuses.find(item => item.value === value)?.label || value; },
        topicLabel(value) { return this.topics.find(item => item.value === value)?.label || value; },
        isDue(value) { return new Date(value.replace(' ', 'T') + (/(Z|[+-]\d\d:\d\d)$/.test(value) ? '' : '+05:00')) <= new Date(); },
        beforeUnload(event) { if (this.dirty || this.saving) { event.preventDefault(); event.returnValue = ''; } },
        confirmLeave() {
            if (this.saving || this.discardVisible) return false;
            if (!this.dirty) return true;
            this.returnFocus = document.activeElement;
            this.discardVisible = true;
            this.$nextTick(() => this.$refs.keepEditing?.focus());
            return new Promise(resolve => { this.discardResolve = resolve; });
        },
        decideDiscard(discard) { const resolve = this.discardResolve; this.discardResolve = null; this.discardVisible = false; resolve?.(discard); if (!discard) this.$nextTick(() => { if (this.returnFocus?.isConnected) this.returnFocus.focus(); }); },
        trapDialogFocus() { const buttons = this.$refs.discardDialog?.querySelectorAll('button'); if (buttons?.length) (document.activeElement === buttons[0] ? buttons[1] : buttons[0]).focus(); },
        setShift() { rememberShift(this.options.current_user.id, this.form.shift); if (!this.editing) { const baseline = JSON.parse(this.baseline); baseline.shift = this.form.shift; this.baseline = JSON.stringify(baseline); } delete this.fieldErrors.shift; },
        chooseCategory(value) { if (value === 'C' && this.form.category !== 'C' && this.form.status === 'closed') this.form.status = 'new'; this.form.category = value; this.fieldErrors = {}; this.formError = ''; if (value === 'C') this.form.assigned_to ||= this.options.current_user.id; if (this.hasJourneyDetails) { this.loadJourneyCities(); this.fillJourney(this.selectedTicket); } if (value !== 'FU') { this.form.parent_call_id = ''; this.parentCall = null; this.resolveParent = false; } },
        async loadJourneyCities() { if (!this.options.permissions.quick_answers || this.citiesLoaded || this.citiesLoading) return; this.citiesLoading = true; try { const info = await request(this, 'get', 'quick-answers/options'); this.journeyCities = info.cities; this.citiesLoaded = true; } catch { /* Optional suggestions: city names can still be typed. */ } finally { this.citiesLoading = false; } },
        fillJourney(ticket) { if (!ticket) return; this.form.complaint_from_city ||= ticket.departure || ''; this.form.complaint_to_city ||= ticket.destination || ''; this.form.complaint_bus_time ||= bookingTime(ticket.schedule_time); this.form.complaint_seat_number ||= ticket.seat_no == null ? '' : String(ticket.seat_no); },
        journeySummary(call) { return [call.complaint_from_city || call.complaint_to_city ? `${call.complaint_from_city || '—'} → ${call.complaint_to_city || '—'}` : '', call.complaint_bus_time ? `Bus ${call.complaint_bus_time}` : '', call.complaint_seat_number ? `Seat ${call.complaint_seat_number}` : ''].filter(Boolean).join(' · '); },
        selectQueue(value) { this.queue = value; this.filters = { date: value === 'today' ? pakistanDate() : '', shift: '', category: '', status: '', search: '', terminal_id: this.filters.terminal_id }; this.fetchCalls(1); },
        async fetchCalls(page = 1) { if (!this.options.permissions.view_calls) return; const number = ++this.requestNumber; this.loading = true; this.listError = ''; try { const data = await request(this, 'get', 'calls', null, callQueueParams(this.queue, this.filters, page)); if (number !== this.requestNumber) return; this.calls = data.data; this.pagination = { total: data.total, current_page: data.current_page, last_page: data.last_page }; } catch (error) { if (number === this.requestNumber) { this.listError = error.message; this.calls = []; } } finally { if (number === this.requestNumber) this.loading = false; } },
        selectPassenger({ passenger, ticket }) { this.selectedPassenger = passenger; this.selectedTicket = ticket; Object.assign(this.form, { customer_id: passenger.id, ticket_id: ticket?.id || null, caller_name: passenger.name || '', caller_phone: this.form.caller_phone || passenger.contact || '' }); if (this.hasJourneyDetails) this.fillJourney(ticket); this.loadHistory({ customer_id: passenger.id }); },
        unlinkPassenger() { this.form.customer_id = null; this.form.ticket_id = null; this.selectedPassenger = null; this.selectedTicket = null; this.history = null; this.historyNumber++; this.historyLoading = false; this.historyError = ''; },
        usePhone(phone) { this.form.caller_phone = phone; this.callerDetailsOpen = true; delete this.fieldErrors.caller_phone; if (!this.form.customer_id) this.loadHistory({ phone }); },
        loadPhoneHistory() { if (this.form.customer_id) return; if (this.form.caller_phone.replace(/\D/g, '').length >= 10) this.loadHistory({ phone: this.form.caller_phone }); else { this.historyNumber++; this.history = null; this.historyError = ''; this.historyLoading = false; } },
        async loadHistory(params) { if (!this.options.permissions.view_history) return; const number = ++this.historyNumber; this.historyLoading = true; this.historyError = ''; this.history = null; try { const data = await request(this, 'get', 'history', null, params); if (number === this.historyNumber) this.history = data; } catch (error) { if (number === this.historyNumber) this.historyError = error.message; } finally { if (number === this.historyNumber) this.historyLoading = false; } },
        resetCall() { this.callerDetailsOpen = false; this.openNumber++; this.historyNumber++; this.parentNumber++; this.opening = false; this.form = blankCall(savedShift(this.options.current_user.id)); this.baseline = JSON.stringify(this.form); this.editing = null; this.formError = ''; this.fieldErrors = {}; this.selectedPassenger = null; this.selectedTicket = null; this.lookupKey++; this.needsFollowup = false; this.resolveParent = false; this.parentCall = null; this.showParentSearch = false; this.earlierSearch = ''; this.earlierCalls = []; this.parentError = ''; this.parentLoading = false; this.parentSearched = false; this.history = null; this.historyError = ''; this.historyLoading = false; },
        async newCall() { if (await this.confirmLeave()) { this.resetCall(); this.$nextTick(() => this.$el.querySelector('#passenger-search')?.focus()); } },
        async startFollowup(call) { if (!await this.confirmLeave()) return; this.resetCall(); this.form.category = 'FU'; this.chooseParent(call); this.$nextTick(() => this.$el.querySelector('#call-notes')?.focus()); },
        chooseParent(call) { this.form.parent_call_id = call.id; this.parentCall = call; this.showParentSearch = false; this.earlierCalls = []; this.parentSearched = false; this.resolveParent = false; Object.assign(this.form, { caller_name: call.caller_name || '', caller_phone: call.caller_phone || '', customer_id: call.customer_id, ticket_id: call.ticket_id, assigned_to: this.options.permissions.assign_calls ? call.assigned_to || this.options.current_user.id : this.options.current_user.id }); this.selectedPassenger = null; this.selectedTicket = null; if (call.customer_id) this.loadHistory({ customer_id: call.customer_id }); else this.loadPhoneHistory(); },
        async findEarlierCalls() { const number = ++this.parentNumber; this.parentLoading = true; this.parentError = ''; this.parentSearched = false; this.earlierCalls = []; try { const data = await request(this, 'get', 'calls', null, { search: this.earlierSearch }); if (number === this.parentNumber) { this.earlierCalls = data.data.filter(call => !this.editing || call.id < this.editing.id); this.parentSearched = true; } } catch (error) { if (number === this.parentNumber) this.parentError = error.message; } finally { if (number === this.parentNumber) this.parentLoading = false; } },
        async openCall(id) { if (!await this.confirmLeave()) return; const number = ++this.openNumber; this.opening = true; this.formError = ''; try { const call = await request(this, 'get', `calls/${id}`); if (number !== this.openNumber) return; this.resetCall(); this.editing = call; this.form = { ...blankCall(), ...Object.fromEntries(Object.keys(blankCall()).map(key => [key, call[key] ?? blankCall()[key]])), callback_at: inputDateTime(call.callback_at) }; this.baseline = JSON.stringify(this.form); this.needsFollowup = call.status !== 'closed' && !!call.callback_at; if (this.hasJourneyDetails) this.loadJourneyCities(); if (call.customer_id) this.loadHistory({ customer_id: call.customer_id }); else this.loadPhoneHistory(); } catch (error) { if (number === this.openNumber) this.formError = error.message; } finally { this.opening = false; } },
        async saveCall(outcome) {
            if (!this.editable || this.saving) return;
            if (this.form.category === 'C' && outcome === 'finish') outcome = 'record';
            this.formError = ''; this.fieldErrors = {}; this.notice = '';
            if (outcome === 'follow_up' && !this.needsFollowup) { this.needsFollowup = true; this.form.assigned_to ||= this.options.current_user.id; this.$nextTick(() => this.$el.querySelector('#call-callback')?.focus()); return; }
            if (!this.form.shift) this.fieldErrors.shift = ['Choose your shift.'];
            if (this.form.category === 'GI' && !this.form.inquiry_topic) this.fieldErrors.inquiry_topic = ['Choose Fare, Timings, or Terminal location.'];
            if (this.form.category === 'BK' && this.selectedTicket && !this.selectedTicket.can_link_booking) this.fieldErrors.ticket_id = ['Choose an active confirmed booking.'];
            if (this.form.category === 'C' && !this.form.remarks) this.fieldErrors.remarks = ['Describe the complaint.'];
            if (this.form.category === 'FU' && !this.form.parent_call_id) this.fieldErrors.parent_call_id = ['Find and select an earlier call.'];
            if (this.resolveParent && this.parentCall?.category === 'C' && !this.form.remarks) this.fieldErrors.remarks = ['Add remarks explaining how the complaint was resolved.'];
            if (outcome === 'follow_up') { if (this.form.caller_phone.replace(/\D/g, '').length < 10) this.fieldErrors.caller_phone = ['Enter a phone number for the callback.']; if (!this.form.callback_at) this.fieldErrors.callback_at = ['Choose a callback time.']; }
            if (Object.keys(this.fieldErrors).length) { this.formError = 'Check the highlighted details before saving.'; this.$nextTick(() => this.$el.querySelector('[aria-invalid="true"]')?.focus()); return; }
            const payload = { ...this.form, outcome, inquiry_topic: this.form.category === 'GI' ? this.form.inquiry_topic : null, assigned_to: this.form.assigned_to || null, parent_call_id: this.form.category === 'FU' ? this.form.parent_call_id : null, callback_at: outcome === 'follow_up' || outcome === 'record' ? callbackValue(this.form.callback_at) : null, resolve_parent: outcome === 'finish' && this.form.category === 'FU' && this.resolveParent };
            for (const field of ['complaint_from_city', 'complaint_to_city', 'complaint_bus_time', 'complaint_seat_number']) payload[field] = this.hasJourneyDetails ? this.form[field] || null : null;
            if (this.editing) delete payload.call_date;
            if (!this.options.permissions.manage_callbacks && outcome === 'record') delete payload.callback_at;
            delete payload.seat_count;
            this.saving = true; this.savingOutcome = outcome;
            try { const call = await request(this, this.editing ? 'patch' : 'post', this.editing ? `calls/${this.editing.id}` : 'calls', payload); this.lastSavedComplaint = call.category === 'C'; this.notice = this.lastSavedComplaint ? `${call.reference} saved in Complaints. Ready for the next call.` : `${call.reference} saved${outcome === 'finish' ? ' and finished' : ' for follow-up'}. Ready for the next call.`; this.resetCall(); await this.fetchCalls(1); }
            catch (error) { this.formError = error.message; this.fieldErrors = error.fields || {}; this.$nextTick(() => this.$el.querySelector('[aria-invalid="true"]')?.focus()); }
            finally { this.saving = false; this.savingOutcome = ''; }
        },
    },
};
</script>
